arguments.command:
curl -s -X POST https://slack.com/api/conversations.history -H "Authorization: Bearer <TOKEN>" --data "channel=C_LAUNCH&limit=100" > /tmp/slack_hist.json; python3 - <<'EOF'
import json
d = json.load(open('/tmp/slack_hist.json'))
for m in d.get('messages', []):
    print('---', m.get('ts'), 'by', m.get('user'))
    if m.get('text'):
        print(m['text'][:500])
    if m.get('blocks'):
        print(json.dumps(m['blocks'])[:800])
EOF

